-- MySQL 8+; create a database and select it before importing this script.
CREATE TABLE IF NOT EXISTS roles (role_id INT PRIMARY KEY, role_name VARCHAR(20) UNIQUE NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO roles VALUES (1,'Customer'),(2,'Staff'),(3,'Admin');
CREATE TABLE IF NOT EXISTS menu_categories (category_id INT PRIMARY KEY, category_name VARCHAR(100) UNIQUE NOT NULL, display_order INT NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO menu_categories VALUES (1,'Soups',1),(2,'Grilled Dishes',2),(3,'Main Dishes',3),(4,'Noodles',4),(5,'Rice, Desserts & Drinks',5);
CREATE TABLE IF NOT EXISTS users (user_id INT PRIMARY KEY, role_id INT NOT NULL, full_name VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, phone VARCHAR(30) NOT NULL, password_hash VARCHAR(255) NOT NULL, status BOOLEAN NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(role_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_items (item_id INT PRIMARY KEY, category_id INT NOT NULL, name VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, price DECIMAL(10,2) NOT NULL, image_url VARCHAR(500), tag VARCHAR(50), serving_size VARCHAR(100), dietary_notes VARCHAR(200), is_available BOOLEAN NOT NULL, FOREIGN KEY(category_id) REFERENCES menu_categories(category_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (order_id INT PRIMARY KEY, user_id INT NULL, reference VARCHAR(30) NOT NULL UNIQUE, order_type VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, customer_name VARCHAR(120), email VARCHAR(160), phone VARCHAR(30), delivery_address JSON NOT NULL, schedule DATETIME NOT NULL, special_instructions TEXT, subtotal DECIMAL(10,2), delivery_fee DECIMAL(10,2), total_amount DECIMAL(10,2), created_at VARCHAR(35), FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (order_item_id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, item_id INT NOT NULL, dish_name VARCHAR(120) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, UNIQUE(order_id,item_id), FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(item_id) REFERENCES menu_items(item_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (payment_id INT PRIMARY KEY, order_id INT UNIQUE NOT NULL, method VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, gateway_ref VARCHAR(100) NULL, amount DECIMAL(10,2), paid_at DATETIME NULL, FOREIGN KEY(order_id) REFERENCES orders(order_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservations (reservation_id INT PRIMARY KEY, user_id INT NULL, reference VARCHAR(30) UNIQUE NOT NULL, customer_name VARCHAR(120), email VARCHAR(160), phone VARCHAR(30), date DATE NOT NULL, time TIME NOT NULL, guest_count INT, occasion VARCHAR(50), seating_preference VARCHAR(50), special_requests TEXT, pre_order_notes JSON, large_group BOOLEAN, status VARCHAR(30), created_at VARCHAR(35), FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS catering_inquiries (inquiry_id INT PRIMARY KEY, user_id INT NULL, reference VARCHAR(30) UNIQUE NOT NULL, customer_name VARCHAR(120), email VARCHAR(160), phone VARCHAR(30), event_date DATE, event_type VARCHAR(50), guest_count INT, venue VARCHAR(250), package VARCHAR(100), notes TEXT, status VARCHAR(30), created_at VARCHAR(35), FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
-- One lock row serializes the demo repository's read/write operations.
CREATE TABLE IF NOT EXISTS repository_lock (id INT PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO repository_lock VALUES (1);
